/* Wizard OS sigils: one solid silhouette, one bite of negative space, one colour per app.
 * GENERATED by tools/sigils/build.py from tools/sigils/sigils.template.js; edit the template, then rebuild.
 *
 *   WizSigil.of(app)    → { glyph, color } for an app record ({ id, name, icon, colors })
 *   WizSigil.html(app)  → '<i class="sgi sg-…">' to drop inside any icon box; the box takes --c
 *   WizSigil.named(glyph, color) → the same for a sigil that isn't an app (search, command rows)
 *
 * Which sigil an app gets: launcher.json `icon` naming a glyph (with `colors[0]` as its colour) wins,
 * then the house set for the Wizard OS apps, then the app's initial on a colour picked from its id.
 * Shapes and the tile style live in core/sigils.css.
 */
(() => {
  'use strict';
  const NAMES = new Set([...["android", "apps", "bag", "bell", "bolt", "burst", "calendar", "chats", "cine", "coffee", "console", "day", "eye", "files", "gauge", "globe", "home", "hub", "iching", "image", "inbox", "letter", "link", "mail", "meditate", "mic", "month", "music", "pin", "projects", "recall", "search", "secret", "shield", "side", "signal", "social", "spark", "track", "usuals", "wave", "week", "wisdom", "wizard"], 'hat', 'hat-private', 'agents']);
  const HOUSE = {"calendar":["calendar","#FE98AB"],"mizel":["mic","#FE9C8C"],"shopping":["bag","#FFA15C"],"wisdom":["wisdom","#FEC25D"],"cinequeue":["cine","#E9CF06"],"trackhunt":["track","#ABE355"],"android-apps":["android","#50DA79"],"topics":["eye","#0ED8BB"],"messenger":["chats","#00D6CF"],"wizard-signal":["signal","#0AD3E3"],"meditation":["meditate","#12CFF6"],"files":["files","#56C8FE"],"wizard-search":["search","#81B7FF"],"projects":["projects","#A0AEFE"],"wizard":["hat","#C1AAFF"],"social":["social","#EF90FE"],"wizard-music":["music","#FF8FD3"],"iching":["iching","#E5C9A3"],"console":["console","#A9B6C4"],"legacy-wizard":["wizard","#BDB5D8"],"v-day":["day","#FF9F6D"],"v-week":["week","#D6A0FE"],"v-month":["month","#99B5E8"],"v-inbox":["inbox","#11DBA2"],"usuals":["usuals","#FE9E79"],"side-button":["side","#C1B1E1"],"maps":["pin","#CDDA2D"],"app-store":["apps","#ABA9FE"],"system":["gauge","#83C9CC"],"notifications":["bell","#FEC076"],"morning-report":["coffee","#FF9F71"],"wizard-calendar":["calendar","#FE98AB"],"secret-drop":["secret","#05D6CE"],"browser":["globe","#11CFF9"],"transcriber":["wave","#F98CF1"],"wizard-chatgpt":["spark","#06DC92"],"wizard-claude":["burst","#FF9C89"],"wizard-tinfoil":["shield","#A1C0CF"],"wizard-agent-service":["hub","#88B9EC"],"agents":["agents","#9BB1F5"]};
  const FALLBACK = ["#FE9A9A", "#FFA332", "#D2D826", "#1DDC8D", "#07D4D6", "#4CCAFF", "#94B1FF", "#C7A8FE", "#FE8AEA"];
  const HEX = /^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const pick = id => { let h = 0; for (const c of String(id)) h = (h * 31 + c.codePointAt(0)) >>> 0; return FALLBACK[h % FALLBACK.length]; };

  function of(a) {
    a = a || {};
    const own = typeof a.icon === 'string' && NAMES.has(a.icon) ? a.icon : '';
    const col = Array.isArray(a.colors) && HEX.test(a.colors[0] || '') ? a.colors[0] : '';
    if (own) return { glyph: own, color: col || (HOUSE[a.id] || [])[1] || pick(a.id) };
    if (HOUSE[a.id]) return { glyph: HOUSE[a.id][0], color: HOUSE[a.id][1] };
    return { glyph: '', color: col || pick(a.id || a.name), letter: String(a.name || a.id || '?').trim().charAt(0).toUpperCase() || '?' };
  }
  function named(glyph, color) {
    return NAMES.has(glyph) ? `<i class="sgi sg-${glyph}" aria-hidden="true"></i>` : `<i class="sgi sgl" aria-hidden="true">${esc(glyph || '?')}</i>`;
  }
  function html(a) { const s = of(a); return s.glyph ? named(s.glyph) : named(s.letter); }
  // A whole icon box: <tag class="cls sgt" style="--c:…">glyph extra</tag>. Apps from the registry carry
  // sgc/sgh already; anything else (a window's fallback, a command row) is worked out here.
  function box(tag, cls, a, extra = '') {
    a = a || {};
    const c = a.sgc || of(a.sigil || a).color, g = a.sgh || html(a.sigil || a);
    return `<${tag} class="${cls ? cls + ' ' : ''}sgt" style="--c:${c}">${g}${extra}</${tag}>`;
  }
  // A sigil that isn't an app (search rows, the command row): glyph name + colour.
  function chip(tag, cls, glyph, color) { return `<${tag} class="${cls ? cls + ' ' : ''}sgt" style="--c:${color}">${named(glyph)}</${tag}>`; }

  window.WizSigil = { of, html, named, box, chip, has: g => NAMES.has(g), house: HOUSE };
})();
